import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";

// ================= DATA =================

const navItems = [
  { name: "Home", id: "home" },
  { name: "About", id: "about" },
  { name: "Fights", id: "fights" },
  { name: "Fighters", id: "fighters" },
  { name: "Origin", id: "origin" },
  { name: "Sponsors", id: "sponsors" },
  { name: "News", id: "news" },
  { name: "Contact", id: "contact" },
];

const features = [
  { icon: "fa-fire", title: "Elite Fights", desc: "High-intensity matchups" },
  { icon: "fa-camera", title: "Story First", desc: "We build fighters" },
  { icon: "fa-users", title: "Youth Culture", desc: "For new generation" },
  { icon: "fa-play-circle-o", title: "Content Engine", desc: "Reels & action" },
  { icon: "fa-globe", title: "Global", desc: "India to world stage" },
];

const fighters = [
  {
    name: "ARJUN MALIK",
    tag1: "THE TECHNICIAN.",
    tag2: "THE THINKER.",
    img: "https://placehold.co/600x800/1a1a1a/red?text=Arjun+Malik",
  },
  {
    name: "MEERA IYER",
    tag1: "THE WARRIOR.",
    tag2: "THE FINISHER.",
    img: "https://placehold.co/600x800/1a1a1a/red?text=Meera+Iyer",
  },
  {
    name: "ZAYN KHAN",
    tag1: "THE PUNISHER.",
    tag2: "THE STORM.",
    img: "https://placehold.co/600x800/1a1a1a/red?text=Zayn+Khan",
  },
];

const sponsorLogos = [
  "https://placehold.co/160x80/222/white?text=Brand+1",
  "https://placehold.co/160x80/222/white?text=Brand+2",
  "https://placehold.co/160x80/222/white?text=Brand+3",
  "https://placehold.co/160x80/222/white?text=Brand+4",
  "https://placehold.co/160x80/222/white?text=Brand+5",
  "https://placehold.co/160x80/222/white?text=Brand+6",
];

const socials = [
  { icon: "fa-instagram", link: "https://instagram.com" },
  { icon: "fa-youtube-play", link: "https://youtube.com" },
  { icon: "fa-facebook", link: "https://facebook.com" },
  { icon: "fa-twitter", link: "https://x.com" },
  { icon: "fa-tiktok", link: "https://tiktok.com" },
];

// ================= COMPONENTS =================

const CountdownBox = ({ value, label }: { value: string; label: string }) => (
  <div className="border border-gray-700 bg-black py-3 sm:py-4 rounded-sm min-w-[65px] sm:min-w-[70px]">
    <p className="text-lg sm:text-xl md:text-2xl font-bold text-white">{value}</p>
    <p className="text-[9px] sm:text-[10px] text-gray-400 uppercase mt-1 tracking-wider">
      {label}
    </p>
  </div>
);

const FeatureCard = ({ icon, title, desc, isLast }: { icon: string; title: string; desc: string; isLast: boolean }) => (
  <div className={`border-r-2 border-[#333] pr-4 ${isLast ? 'border-none' : ''}`}>
    <i className={`fa ${icon} text-red-500 text-2xl mb-3`} />
    <h3 className="text-xs font-bold uppercase mb-1">{title}</h3>
    <p className="text-xs text-gray-500">{desc}</p>
  </div>
);

const FighterCard = ({ fighter }: { fighter: typeof fighters[0] }) => (
  <div className="relative bg-[#0c0c0c] border border-gray-800 overflow-hidden group rounded-md">
    <img src={fighter.img} alt={fighter.name} className="h-[340px] w-full object-cover" />
    <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-transparent" />
    <div className="absolute bottom-0 p-4 text-center w-full">
      <h3 className="font-bold text-sm tracking-wide uppercase">{fighter.name}</h3>
      <p className="text-red-600 text-xs uppercase mt-1">{fighter.tag1}</p>
      <p className="text-red-600 text-xs uppercase">{fighter.tag2}</p>
      <button className="mt-3 border border-gray-600 px-4 py-1 text-[10px] uppercase hover:bg-white hover:text-black transition rounded-sm">
        VIEW PROFILE
      </button>
    </div>
  </div>
);

// ================= MAIN COMPONENT =================

export default function LandingPage() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [timeLeft, setTimeLeft] = useState({
    days: "00",
    hours: "00",
    minutes: "00",
    seconds: "00",
  });

  const eventDate = new Date("2026-06-30T18:00:00").getTime();

  const getTimeRemaining = () => {
    const now = new Date().getTime();
    const distance = eventDate - now;

    if (distance <= 0) {
      return { days: "00", hours: "00", minutes: "00", seconds: "00" };
    }

    return {
      days: String(Math.floor(distance / (1000 * 60 * 60 * 24))).padStart(2, "0"),
      hours: String(Math.floor((distance / (1000 * 60 * 60)) % 24)).padStart(2, "0"),
      minutes: String(Math.floor((distance / (1000 * 60)) % 60)).padStart(2, "0"),
      seconds: String(Math.floor((distance / 1000) % 60)).padStart(2, "0"),
    };
  };

  useEffect(() => {
    const updateTime = () => setTimeLeft(getTimeRemaining());
    updateTime();
    const timer = setInterval(updateTime, 1000);
    return () => clearInterval(timer);
  }, []);

  const handleScroll = (id: string) => {
    let targetId = id;
    if (id === "fights") targetId = "about";
    if (id === "news") targetId = "sponsors";
    if (id === "contact") targetId = "sponsors";

    const section = document.getElementById(targetId);
    if (section) {
      section.scrollIntoView({ behavior: "smooth", block: "start" });
    }
    setMenuOpen(false);
  };

  return (
    <div className="bg-black text-white font-[Inter] overflow-x-hidden">
      {/* ================= NAVBAR ================= */}
      <nav className="fixed w-full z-50 bg-black/90 border-b border-neutral-900 backdrop-blur-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          {/* Logo */}
          <div className="flex items-center shrink-0">
            <img
              src="https://placehold.co/200x80/1a1a1a/red?text=GFC+LOGO"
              alt="GFC Logo"
              className="h-10 sm:h-12 md:h-14 xl:h-16 w-auto object-contain"
            />
          </div>

          {/* Desktop Navigation */}
          <ul className="hidden md:flex gap-6 lg:gap-8 text-xs uppercase tracking-wider font-semibold">
            {navItems.map((item) => (
              <li
                key={item.id}
                onClick={() => handleScroll(item.id)}
                className="hover:text-red-500 transition cursor-pointer"
              >
                {item.name}
              </li>
            ))}
          </ul>

          {/* Mobile Menu Button */}
          <button onClick={() => setMenuOpen(!menuOpen)} className="md:hidden text-white text-2xl focus:outline-none">
            ☰
          </button>

          {/* Desktop Ticket Button */}
          <button className="hidden sm:block bg-red-600 px-4 py-2 text-xs font-semibold rounded-sm hover:bg-red-700 transition">
            GET TICKETS
          </button>
        </div>

        {/* Mobile Dropdown Menu */}
        {menuOpen && (
          <div className="md:hidden bg-black border-t border-neutral-800 flex flex-col items-center py-6 gap-4 text-sm uppercase">
            {navItems.map((item) => (
              <div
                key={item.id}
                onClick={() => handleScroll(item.id)}
                className="hover:text-red-500 cursor-pointer"
              >
                {item.name}
              </div>
            ))}
            <button className="bg-red-600 px-6 py-2 text-xs font-semibold mt-2 w-40 rounded-sm">
              GET TICKETS
            </button>
          </div>
        )}
      </nav>

      {/* ================= HERO SECTION ================= */}
      <section id="home" className="relative pt-20 md:pt-24 flex items-center min-h-[90vh] md:min-h-screen overflow-hidden">
        {/* Gradient Overlay */}
        <div className="absolute inset-0 bg-gradient-to-r from-black via-black/90 to-transparent z-0" />

        {/* Background Fighter Image */}
        <div className="absolute right-0 top-0 bottom-0 w-full flex justify-end pointer-events-none">
          <img
            src="https://placehold.co/1200x900/2a2a2a/red?text=Fighter"
            alt="fighter"
            className="w-[85%] sm:w-[75%] md:w-[65%] lg:w-[55%] xl:w-[50%] max-w-[900px] object-contain opacity-60 md:opacity-70 absolute right-0 bottom-0 md:top-1/2 md:transform md:-translate-y-1/2"
          />
        </div>

        {/* Hero Content */}
        <div className="relative z-10 max-w-7xl mx-auto w-full px-5 sm:px-8 lg:px-10 py-12 md:py-16">
          <div className="w-full max-w-full sm:max-w-[550px] lg:max-w-[700px]">
            <p className="text-red-500 text-xs uppercase tracking-[3px] mb-3">GFC GLOBAL 1: ORIGIN</p>
            <h1 className="font-[Anton] italic uppercase tracking-[1px] leading-[1.1] text-[40px] sm:text-[55px] md:text-[80px] lg:text-[100px] xl:text-[120px]">
              <span className="block">FIGHTS.</span>
              <span className="block">STORIES.</span>
              <span className="block text-red-500">LEGENDS.</span>
            </h1>
            <p className="mt-4 text-gray-300 text-sm sm:text-base max-w-md">
              India's Next Combat Sports Movement
            </p>
            <div className="flex flex-col sm:flex-row gap-4 mt-8">
              <button className="bg-red-600 px-6 py-3 text-xs sm:text-sm font-semibold rounded-sm hover:bg-red-700 transition">
                GET TICKETS
              </button>
              <button className="border border-white px-6 py-3 text-xs sm:text-sm rounded-sm hover:bg-white/10 transition">
                ▶ WATCH TRAILER
              </button>
            </div>
          </div>
        </div>
      </section>

      {/* ================= FEATURES SECTION ================= */}
      <section id="about" className="border-t border-neutral-900 bg-black">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-10 py-12">
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-6 text-center">
            {features.map((item, i) => (
              <FeatureCard
                key={i}
                icon={item.icon}
                title={item.title}
                desc={item.desc}
                isLast={i === features.length - 1}
              />
            ))}
          </div>
        </div>
      </section>

      {/* ================= ABOUT + FIGHTERS SECTION ================= */}
      <section id="fighters" className="max-w-7xl mx-auto px-5 sm:px-8 py-16 md:py-20">
        <div className="grid lg:grid-cols-2 gap-12 items-start">
          {/* Left Text Content */}
          <div className="max-w-md mx-auto lg:mx-0">
            <p className="text-red-600 text-xs tracking-widest uppercase mb-3">ABOUT GFC</p>
            <h2 className="text-3xl md:text-4xl font-extrabold leading-tight uppercase">
              WE ARE BUILDING <br />
              MORE THAN EVENTS.
              <br />
              <span className="text-red-600">WE ARE BUILDING A MOVEMENT.</span>
            </h2>
            <p className="text-gray-400 text-sm mt-5 leading-relaxed">
              GFC is a combat sports platform focused on fighters, content and culture.
              Our mission is to give fighters the stage they deserve and fans the
              experience they will never forget.
            </p>
            <button className="mt-6 border border-gray-600 px-5 py-2 text-sm uppercase hover:bg-white hover:text-black transition rounded-sm">
              KNOW MORE →
            </button>
          </div>

          {/* Fighters Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {fighters.map((fighter, i) => (
              <FighterCard key={i} fighter={fighter} />
            ))}
          </div>
        </div>
      </section>

      {/* ================= EVENT + COUNTDOWN SECTION ================= */}
      <section id="origin" className="border-t border-gray-800 bg-[#0a0a0a] py-12 md:py-16">
        <div className="max-w-7xl mx-auto px-5 sm:px-8 lg:px-10">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-center">
            {/* Event Poster */}
            <div className="flex justify-center lg:justify-start">
